const UNITS = ["B", "KB", "MB", "GB", "TB"];

export function bytes(value, lang = "en") {
  if (value === null || value === undefined || Number.isNaN(value)) return "–";
  let v = Math.abs(value);
  let i = 0;
  while (v >= 1024 && i < UNITS.length - 1) {
    v /= 1024;
    i += 1;
  }
  const digits = v >= 100 || i === 0 ? 0 : v >= 10 ? 1 : 2;
  const num = new Intl.NumberFormat(lang, { maximumFractionDigits: digits }).format(v);
  return `${value < 0 ? "−" : ""}${num} ${UNITS[i]}`;
}

export function number(value, lang = "en") {
  if (value === null || value === undefined) return "–";
  return new Intl.NumberFormat(lang).format(value);
}

export function percent(value, lang = "en") {
  return new Intl.NumberFormat(lang, { style: "percent", maximumFractionDigits: 0 }).format(value);
}

export function relativeTime(ts, t, lang = "en") {
  if (!ts) return t("never");
  const seconds = Math.round(Date.now() / 1000 - ts);
  if (seconds < 60) return t("just_now");
  const rtf = new Intl.RelativeTimeFormat(lang, { numeric: "auto" });
  const steps = [
    [60, "second"],
    [60, "minute"],
    [24, "hour"],
    [7, "day"],
    [4.35, "week"],
    [12, "month"],
    [Number.POSITIVE_INFINITY, "year"],
  ];
  let value = seconds;
  for (const [size, unit] of steps) {
    if (Math.abs(value) < size) return rtf.format(-Math.round(value), unit);
    value /= size;
  }
  return "";
}

export function dateTime(value, lang = "en") {
  if (!value) return "–";
  const d = typeof value === "number" ? new Date(value * 1000) : new Date(value);
  return new Intl.DateTimeFormat(lang, { dateStyle: "medium", timeStyle: "short" }).format(d);
}
